exports.code = async (inputs) => {
  const incident = inputs.body;
  return {
    incident_id: incident.incident_id || 'UNKNOWN',
    service_name: incident.service_name || 'unknown-service',
    risk_score: incident.risk_score || 0,
    root_cause: incident.root_cause || incident.routing_reason || 'Pending investigation',
    confidence: incident.confidence || 0,
    playbook_steps: incident.remediation_playbook || []
  };
};

exports.code = async (inputs) => {
  const data = inputs.parsed;
  return {
    title: `[Synapse RiskOps] Escalation: ${data.service_name} (Risk: ${data.risk_score})`,
    description: `### Incident Details
- **ID**: ${data.incident_id}
- **Service**: ${data.service_name}
- **Risk Score**: ${data.risk_score}
- **Confidence**: ${(data.confidence * 100).toFixed(1)}%

### Root Cause Analysis
${data.root_cause}

### Recommended Actions
${(data.playbook_steps || []).map((s, i) => `${i+1}. ${s}`).join('
')}`
  };
};
